{"path":"pricing.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Pricing — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfaf7;--card:#fff;--muted:#6b6b6b;--accent:#7aa27a;--accent-2:#c78cdd;--glass:rgba(255,255,255,0.6)}
    *{box-sizing:border-box}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#222;background:linear-gradient(180deg,var(--bg),#f4f7f5);margin:0}
    header{padding:20px 28px;display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;background:rgba(255,255,255,0.66);backdrop-filter:blur(6px);border-bottom:1px solid #eee}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:46px;height:46px;background:var(--accent);display:flex;align-items:center;justify-content:center;border-radius:10px;color:white;font-weight:700}
    nav a{margin-left:18px;color:#2b2b2b;text-decoration:none;font-weight:600}
    main{max-width:1100px;margin:28px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr 320px;gap:24px;align-items:start;margin-bottom:22px}
    .hero .lead{background:var(--card);padding:22px;border-radius:12px;box-shadow:0 6px 20px rgba(20,30,20,0.06)}
    h1{margin:0 0 8px 0;font-size:22px}
    p.lead{margin:0;color:var(--muted)}
    .side-card{background:linear-gradient(180deg,var(--glass),transparent);padding:18px;border:1px dashed #e8efe8;border-radius:12px}
    .grid{display:grid;grid-template-columns:repeat(auto-fit, minmax(240px,1fr));gap:18px;margin-top:18px}
    .plan{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 20px rgba(10,10,10,0.04);border-top:4px solid rgba(0,0,0,0.02)}
    .plan h3{margin:0 0 8px 0}
    .price{font-weight:700;font-size:20px;color:var(--accent)}
    .muted{color:var(--muted);font-size:14px}
    .cta{display:inline-block;margin-top:12px;padding:8px 12px;border-radius:8px;background:var(--accent);color:white;text-decoration:none}
    .secondary{background:#fff;border:1px solid #ddd;color:#333}
    .small{font-size:13px}
    .faq{margin-top:22px}
    details{background:#fff;padding:14px;border-radius:10px;margin-bottom:10px}
    footer{margin:40px 0 80px 0;color:var(--muted);text-align:center}
    /* Blend builder */
    .builder{margin-top:18px;padding:14px;background:linear-gradient(180deg,rgba(199,140,221,0.06),rgba(122,162,122,0.03));border-radius:10px}
    label{display:block;margin-top:8px;font-weight:600}
    select,input[type='range']{width:100%;padding:8px;border-radius:8px;border:1px solid #ddd;margin-top:6px}
    button{cursor:pointer}
    .card-out{margin-top:12px;padding:12px;border-radius:8px;background:#fff;border:1px solid #eee}
    .copy{margin-top:8px;padding:8px 10px;border-radius:8px;border:1px dashed #bbb;background:transparent}
  </style>
</head>
<body>
  <header>
    <div class='brand'>
      <div class='logo'>AR</div>
      <div>
        <div style='font-weight:700'>{{BUSINESS_NAME}}</div>
        <div style='font-size:13px;color:var(--muted)'>Holistic aroma events & small-group sessions</div>
      </div>
    </div>
    <nav aria-label='primary'>
      <a href='index.html'>Start</a>
      <a href='services.html'>Gatherings</a>
      <a href='blends.html'>Blends</a>
      <a href='shop.html'>Store</a>
      <a href='pricing.html'>Rates</a>
      <a href='about.html'>Our Story</a>
      <a href='book.html'>Reserve</a>
      <a href='contact.html'>Say Hello</a>
    </nav>
  </header>

  <main>
    <section class='hero'>
      <div class='lead'>
        <h1>Transparent session pricing and small-course passes</h1>
        <p class='lead'>Tailored timeframes for single sessions, ongoing support, and episodic classes. Our options are framed to meet people where they are — practical, time-conscious, and safety-first.</p>

        <div class='grid'>
          <div class='plan'>
            <h3>Intro Session</h3>
            <div class='price'>$85</div>
            <div class='muted small'>60 minutes — consultation + aromatherapy plan</div>
            <a class='cta' href='book.html'>Reserve a slot</a>
          </div>

          <div class='plan'>
            <h3>Focused Follow-up</h3>
            <div class='price'>$60</div>
            <div class='muted small'>30 minutes — check-in & plan refinement</div>
            <a class='cta secondary' href='book.html'>Book follow-up</a>
          </div>

          <div class='plan'>
            <h3>Series Pass — 4 sessions</h3>
            <div class='price'>$320</div>
            <div class='muted small'>One introductory + three shorter sessions. Save 10% compared to singles.</div>
            <a class='cta' href='book.html'>Claim a pass</a>
          </div>
        </div>
      </div>

      <aside class='side-card'>
        <h4 style='margin:0 0 6px 0'>What your session includes</h4>
        <p class='small muted'>A clear scent plan, suggested timings, a blend note you can make at home, and safe dilution guidance. No claims of cures — just practical scent supports that may help with day-to-day balance.</p>

        <div style='margin-top:10px'>
          <div style='font-weight:700'>Private events</div>
          <div class='muted small'>Custom small-group scent workshops. Email {{EMAIL}} for proposals.</div>
        </div>
      </aside>
    </section>

    <section>
      <h2 style='margin-bottom:8px'>A la carte add-ons</h2>
      <div class='grid'>
        <div class='plan'>
          <h3>Personal Blend Card</h3>
          <div class='price'>$28</div>
          <div class='muted small'>A printed note and recipe for one day-to-week scent card, safe dilution included.</div>
        </div>
        <div class='plan'>
          <h3>Mini-workshop (90 min)</h3>
          <div class='price'>$150</div>
          <div class='muted small'>Up to 6 people. Teach simple, safe blending and inhalation approaches.</div>
        </div>
      </div>
    </section>

    <section class='builder'>
      <h3 style='margin:0'>Blend Builder — quick guidance</h3>
      <p class='small muted'>Choose a mood and get a gentle recipe and clearly labeled dilution guidance. For informational use only.</p>

      <label for='vibe'>Vibe</label>
      <select id='vibe'>
        <option value='calm'>Calm & even</option>
        <option value='focus'>Alert focus</option>
        <option value='sleep'>Evening wind-down</option>
        <option value='uplift'>Bright uplift</option>
      </select>

      <label for='bottle'>Bottle size</label>
      <select id='bottle'>
        <option value='10'>10 mL</option>
        <option value='30'>30 mL</option>
      </select>

      <label for='dilution'>Dilution strength</label>
      <select id='dilution'>
        <option value='1'>1% (gentle)</option>
        <option value='2'>2% (standard)</option>
        <option value='3'>3% (robust)</option>
      </select>

      <div style='display:flex;gap:8px;margin-top:10px'>
        <button id='build' class='cta'>Build recipe</button>
        <button id='clear' class='secondary'>Reset</button>
      </div>

      <div id='result' class='card-out' aria-live='polite'>Select options and click "Build recipe" to see a friendly blend card.</div>
    </section>

    <section class='faq'>
      <h3>FAQ — safety first</h3>
      <details>
        <summary>What does dilution mean here?</summary>
        <p class='small muted'>Dilution is the percentage of essential oil in a carrier (like jojoba or fractionated coconut). It is presented as a guide. For 10 mL, 1% is roughly 2 drops; 2% ~4 drops; 3% ~6 drops. For 30 mL, 1% ~6 drops; 2% ~12 drops; 3% ~18 drops. These are approximations based on an average of ~20 drops per mL.</p>
      </details>

      <details>
        <summary>Do I need a patch test?</summary>
        <p class='small muted'>Yes — test any new topical blend on a small area of skin and wait 24 hours. Discontinue if irritation occurs. Avoid applying undiluted essential oils directly to skin.</p>
      </details>

      <details>
        <summary>Any considerations for pets or pregnancy?</summary>
        <p class='small muted'>Many oils can affect pets or are not recommended during pregnancy. If pregnant, nursing, or keeping pets, consult your care provider or a veterinarian before using essential oils. Our guidance is precautionary and not medical advice.</p>
      </details>
    </section>

    <footer>
      <div style='font-weight:700'>Ready to try a plan?</div>
      <div class='muted small'>Book a session or drop a line at {{EMAIL}} — phone {{PHONE}}</div>
    </footer>
  </main>

<script>
(function(){
  // Blend builder logic
  function oilOptionsFor(vibe){
    const map = {
      calm:['Sweet Orange','Lavender','Bergamot'],
      focus:['Rosemary','Peppermint','Lemon'],
      sleep:['Lavender','Cedarwood','Sweet Marjoram'],
      uplift:['Grapefruit','Bergamot','Ginger']
    };
    return map[vibe] || ['Lavender','Sweet Orange','Frankincense'];
  }

  function buildCard(){
    const vibe = document.getElementById('vibe').value;
    const bottle = Number(document.getElementById('bottle').value);
    const dilution = Number(document.getElementById('dilution').value);
    const oils = oilOptionsFor(vibe);
    // rough math: assume 20 drops per mL
    const dropsPerMl = 20;
    const totalDrops = Math.round(dropsPerMl * bottle);
    const dropsNeeded = Math.max(1, Math.round(totalDrops * (dilution/100)));

    const distribution = [Math.max(1,Math.round(dropsNeeded*0.5)), Math.max(1,Math.round(dropsNeeded*0.3)), Math.max(0,dropsNeeded - Math.max(1,Math.round(dropsNeeded*0.5)) - Math.max(1,Math.round(dropsNeeded*0.3)))];

    let out = '';
    out += 'Blend card — ' + vibe.charAt(0).toUpperCase()+vibe.slice(1) + ' \n';
    out += 'Bottle: ' + bottle + ' mL — Dilution: ' + dilution + '%\n\n';
    out += 'Recipe (drops):\n';
    oils.forEach(function(o,i){ out += '- ' + oils[i] + ': ' + (distribution[i]||0) + ' drops\n'; });
    out += '\nDilution guide: approx ' + dropsNeeded + ' total drops in ' + bottle + ' mL.\n';
    out += 'Notes: Patch test before topical use. Avoid undiluted application. If pregnant, nursing, or around sensitive pets, seek guidance before use. This is informational only and not medical advice.';

    document.getElementById('result').textContent = out;
  }

  document.getElementById('build').addEventListener('click', function(){ buildCard(); });
  document.getElementById('clear').addEventListener('click', function(){ document.getElementById('result').textContent = 'Select options and click "Build recipe" to see a friendly blend card.'; });

})();
</script>
</body>
</html>"} 
