<script>
(function(){
  // Session planner logic
  function buildPlanText(){
    const name = document.getElementById('name').value || '[Name]';
    const email = document.getElementById('email').value || '[Email]';
    const service = document.getElementById('service').value;
    const date = document.getElementById('date').value || '[Preferred date]';
    const notes = document.getElementById('notes').value || '';

    const goal = document.getElementById('goal').value;
    const freq = document.getElementById('freq').value;
    const delivery = document.getElementById('delivery').value;
    const length = document.getElementById('length').value;

    let out = '';
    out += 'Session planner — personal summary\n';
    out += 'Name: '+name+'\n';
    out += 'Email: '+email+'\n';
    out += 'Requested service: '+service+'\n';
    out += 'Preferred date: '+date+'\n\n';
    out += 'Goal: '+goal+'\n';
    out += 'Frequency: '+freq+'\n';
    out += 'Delivery: '+delivery+'\n';
    out += 'Session length: '+length+' minutes\n\n';
    if(notes) out += 'Notes: '+notes+'\n\n';
    out += 'Safety notes: Patch test recommended for topical blends; avoid undiluted oils. If pregnant, nursing, or with pets, mention at booking. This is informational and not medical advice.';

    return out;
  }

  document.getElementById('buildPlan').addEventListener('click', function(){
    const txt = buildPlanText();
    document.getElementById('planOut').textContent = txt;
  });

  document.getElementById('planCopy').addEventListener('click', function(){
    const txt = buildPlanText();
    navigator.clipboard && navigator.clipboard.writeText(txt).then(function(){
      alert('Plan copied to clipboard');
    }, function(){
      alert('Copy failed — please select and copy manually');
    });
  });

  document.getElementById('downloadPlan').addEventListener('click', function(){
    const txt = buildPlanText();
    const blob = new Blob([txt], {type: 'text/plain'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'session-plan.txt';
    document.body.appendChild(a); a.click(); a.remove();
    URL.revokeObjectURL(url);
  });

  document.getElementById('submit').addEventListener('click', function(){
    alert('Request sent. We will follow up to confirm availability.');
  });
})();
</script>
